def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation.get('resources', [])
    opponent_x, opponent_y = observation['opponent_position']

    def is_valid(nx, ny):
        return 0 <= nx < width and 0 <= ny < height and (nx, ny) not in observation.get('obstacles', [])

    # Move towards nearest resource if any
    if resources:
        rx, ry = min(resources, key=lambda r: abs(r['position'][0]-x)+abs(r['position'][1]-y))['position']
        dx = (rx - x) and (1 if rx > x else -1)
        dy = (ry - y) and (1 if ry > y else -1)
        if is_valid(x + dx, y + dy):
            return [dx, dy]
        if is_valid(x + (1 if rx > x else -1), y):
            return [1 if rx > x else -1, 0]
        if is_valid(x, y + (1 if ry > y else -1)):
            return [0, 1 if ry > y else -1]
        # fallback stay
        return [0, 0]
    # Else move towards opponent
    dx = (opponent_x - x) and (1 if opponent_x > x else -1)
    dy = (opponent_y - y) and (1 if opponent_y > y else -1)
    if is_valid(x + dx, y + dy):
        return [dx, dy]
    if is_valid(x + (1 if opponent_x > x else -1), y):
        return [1 if opponent_x > x else -1, 0]
    if is_valid(x, y + (1 if opponent_y > y else -1)):
        return [0, 1 if opponent_y > y else -1]
    return [0, 0]
